namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        Add("Welcome to the app!");
        Add("Your profile was updated.");
        Add("New feature: dark mode is available.");
    }

    public Task<List<Notification>> GetAllAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetSinceAsync(int lastSeenId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId).ToList());
        }
    }

    /// <summary>Simulates a new notification arriving at random intervals.</summary>
    public void SimulateIncoming()
    {
        if (Random.Shared.NextDouble() < 0.4)
        {
            var messages = new[]
            {
                "You have a new follower!",
                "Someone liked your post.",
                "Scheduled maintenance tonight at 11 PM.",
                "Your export is ready to download.",
                "A teammate mentioned you in a comment.",
                "Weekly digest is available.",
            };
            Add(messages[Random.Shared.Next(messages.Length)]);
        }
    }

    private void Add(string message)
    {
        lock (_lock)
        {
            _notifications.Add(new Notification(_nextId++, message, DateTime.UtcNow));
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
