     [PersistentState]
     public List<Notification>? RestoredNotifications { get; set; }

     private List<Notification> notifications = new();
     private int lastSeenId;
     private CancellationTokenSource? cts;

     protected override async Task OnInitializedAsync()
     {
         RestoredNotifications ??= await NotificationSvc.GetAllAsync();
         notifications = RestoredNotifications;
         lastSeenId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
     }

     protected override void OnAfterRender(bool firstRender)
     {
         if (firstRender)
         {
             // Only runs after the interactive runtime attaches — never during prerender
             cts = new CancellationTokenSource();
             _ = PollForNotificationsAsync(cts.Token);
         }
     }

     private async Task PollForNotificationsAsync(CancellationToken token)
     {
         while (!token.IsCancellationRequested)
         {
             await Task.Delay(5000, token);

             NotificationSvc.SimulateIncoming();
             var newer = await NotificationSvc.GetSinceAsync(lastSeenId);

             if (newer.Count > 0)
             {
                 notifications.AddRange(newer);
                 lastSeenId = newer.Max(n => n.Id);
                 await InvokeAsync(StateHasChanged);
             }
         }
     }

     public async ValueTask DisposeAsync()
     {
         if (cts is not null)
         {
             await cts.CancelAsync();
             cts.Dispose();
         }
     }
 }

